const body = $json.body || $json;

const durationHours = Number(body.durationHours);
const amountInCents = Number(body.amountInCents);
const currency = body.currency || 'COP';
const timezone = body.timezone || 'America/Bogota';

const requiredFields = [
  'fullName',
  'email',
  'phone',
  'selectedStart',
  'selectedEnd',
  'businessType',
  'needType',
  'projectStage',
  'message',
];

for (const field of requiredFields) {
  if (!String(body[field] || '').trim()) {
    return [{ json: { ok: false, statusCode: 400, message: `Missing field: ${field}` } }];
  }
}

if (![1, 2, 3].includes(durationHours)) {
  return [{ json: { ok: false, statusCode: 400, message: 'durationHours must be 1, 2 or 3.' } }];
}

const expectedAmount = durationHours * 75000 * 100;

if (amountInCents !== expectedAmount) {
  return [{ json: { ok: false, statusCode: 400, message: 'Invalid amount.' } }];
}

if (currency !== 'COP') {
  return [{ json: { ok: false, statusCode: 400, message: 'Invalid currency.' } }];
}

const startsAt = new Date(body.selectedStart);
const endsAt = new Date(body.selectedEnd);

if (Number.isNaN(startsAt.getTime()) || Number.isNaN(endsAt.getTime())) {
  return [{ json: { ok: false, statusCode: 400, message: 'Invalid selectedStart or selectedEnd.' } }];
}

const diffHours = (endsAt.getTime() - startsAt.getTime()) / (60 * 60 * 1000);

if (diffHours !== durationHours) {
  return [{ json: { ok: false, statusCode: 400, message: 'Selected slot does not match duration.' } }];
}

const colombiaParts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'America/Bogota',
  weekday: 'short',
  hour: '2-digit',
  minute: '2-digit',
  hour12: false,
}).formatToParts(startsAt);

const weekday = colombiaParts.find((part) => part.type === 'weekday')?.value;
const hour = Number(colombiaParts.find((part) => part.type === 'hour')?.value);
const minute = Number(colombiaParts.find((part) => part.type === 'minute')?.value);

if (minute !== 0) {
  return [{ json: { ok: false, statusCode: 400, message: 'Bookings must start on exact hours.' } }];
}

if (weekday === 'Sun') {
  return [{ json: { ok: false, statusCode: 400, message: 'Sunday is not bookable.' } }];
}

if (weekday === 'Sat' && hour + durationHours > 14) {
  return [{ json: { ok: false, statusCode: 400, message: 'Saturday bookings must end by 14:00.' } }];
}

const bookingUuid = crypto.randomUUID();
const reference = `booking_${bookingUuid}`;
const redirectUrl = 'https://himayrob.com/consultoria/gracias';

return [{
  json: {
    ok: true,
    fullName: String(body.fullName).trim(),
    email: String(body.email).trim().toLowerCase(),
    phone: String(body.phone).trim(),
    businessType: body.businessType,
    needType: body.needType,
    projectStage: body.projectStage,
    message: body.message,
    source: body.source || 'web-consultoria-horas',
    durationHours,
    startsAt: startsAt.toISOString(),
    endsAt: endsAt.toISOString(),
    timezone,
    amountInCents,
    currency,
    reference,
    redirectUrl,
  }
}];

const booking = $('Postgres - Create Pending Booking').first()?.json;
const request = $('Validate Init Payment').first().json;

if (!booking?.wompi_reference) {
  return [{
    json: {
      ok: false,
      statusCode: 409,
      message: 'This slot is no longer available.',
    }
  }];
}

const publicKey = 'REPLACE_WITH_WOMPI_PUBLIC_KEY';
const integritySecret = 'REPLACE_WITH_WOMPI_INTEGRITY_SECRET';

const reference = booking.wompi_reference;
const amountInCents = Number(booking.amount_in_cents);
const currency = booking.currency || 'COP';
const text = String(reference) + String(amountInCents) + String(currency) + String(integritySecret);

function rightRotate(value, amount) {
  return (value >>> amount) | (value << (32 - amount));
}

function sha256(ascii) {
  const mathPow = Math.pow;
  const maxWord = mathPow(2, 32);
  const lengthProperty = 'length';
  let i;
  let j;
  const words = [];
  const asciiBitLength = ascii[lengthProperty] * 8;
  let hash = sha256.h = sha256.h || [];
  const k = sha256.k = sha256.k || [];
  let primeCounter = k[lengthProperty];
  const isComposite = {};

  for (let candidate = 2; primeCounter < 64; candidate++) {
    if (!isComposite[candidate]) {
      for (i = 0; i < 313; i += candidate) isComposite[i] = candidate;
      hash[primeCounter] = (mathPow(candidate, 0.5) * maxWord) | 0;
      k[primeCounter++] = (mathPow(candidate, 1 / 3) * maxWord) | 0;
    }
  }

  ascii += '\x80';
  while (ascii[lengthProperty] % 64 - 56) ascii += '\x00';

  for (i = 0; i < ascii[lengthProperty]; i++) {
    j = ascii.charCodeAt(i);
    if (j >> 8) return '';
    words[i >> 2] |= j << (((3 - i) % 4) * 8);
  }

  words[words[lengthProperty]] = (asciiBitLength / maxWord) | 0;
  words[words[lengthProperty]] = asciiBitLength;

  for (j = 0; j < words[lengthProperty];) {
    const w = words.slice(j, j += 16);
    const oldHash = hash;
    hash = hash.slice(0, 8);

    for (i = 0; i < 64; i++) {
      const w15 = w[i - 15];
      const w2 = w[i - 2];
      const a = hash[0];
      const e = hash[4];
      const temp1 =
        hash[7] +
        (rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25)) +
        ((e & hash[5]) ^ ((~e) & hash[6])) +
        k[i] +
        (w[i] = i < 16
          ? w[i]
          : (w[i - 16] +
              (rightRotate(w15, 7) ^ rightRotate(w15, 18) ^ (w15 >>> 3)) +
              w[i - 7] +
              (rightRotate(w2, 17) ^ rightRotate(w2, 19) ^ (w2 >>> 10))) | 0);
      const temp2 =
        (rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22)) +
        ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));
      hash = [(temp1 + temp2) | 0].concat(hash);
      hash[4] = (hash[4] + temp1) | 0;
    }

    for (i = 0; i < 8; i++) hash[i] = (hash[i] + oldHash[i]) | 0;
  }

  let hex = '';
  for (i = 0; i < 8; i++) {
    for (j = 3; j + 1; j--) {
      const b = (hash[i] >> (j * 8)) & 255;
      hex += ((b < 16) ? '0' : '') + b.toString(16);
    }
  }
  return hex;
}

const integrity = sha256(text);

return [{
  json: {
    ok: true,
    reference,
    amountInCents,
    currency,
    redirectUrl: request.redirectUrl,
    integrity,
    publicKey,
    bookingId: booking.booking_id,
  }
}];
